@page "/settings"
@using sv_e2ba79d9bc654a718f264d7e2b905c7b.Services
@inject ISettingsService SettingsService
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-container">
    <nav class="settings-sidebar">
        <ul>
            <li class="@(ActiveSection == "Profile" ? "active" : "")" @onclick='() => SetSection("Profile")'>
                <span class="nav-icon">👤</span> Profile
            </li>
            <li class="@(ActiveSection == "Notifications" ? "active" : "")" @onclick='() => SetSection("Notifications")'>
                <span class="nav-icon">🔔</span> Notifications
            </li>
            <li class="@(ActiveSection == "Security" ? "active" : "")" @onclick='() => SetSection("Security")'>
                <span class="nav-icon">🔒</span> Security
            </li>
            <li class="@(ActiveSection == "Appearance" ? "active" : "")" @onclick='() => SetSection("Appearance")'>
                <span class="nav-icon">🎨</span> Appearance
            </li>
        </ul>
    </nav>

    <main class="settings-content">
        @if (!string.IsNullOrEmpty(ToastMessage))
        {
            <div class="toast @ToastType">
                @ToastMessage
                <button class="toast-close" @onclick="DismissToast">✕</button>
            </div>
        }

        @if (ActiveSection == "Profile")
        {
            <section class="settings-section">
                <h2>Profile Settings</h2>
                @if (Profile is not null)
                {
                    <div class="profile-layout">
                        <div class="avatar-area">
                            <img src="@EditDisplayAvatarUrl" alt="Avatar" class="avatar-preview" />
                            <p class="avatar-url-label">Avatar URL:</p>
                            <input type="text" @bind="EditDisplayAvatarUrl" class="form-input" />
                        </div>
                        <div class="profile-fields">
                            <div class="form-group">
                                <label>Display Name</label>
                                <input type="text" @bind="EditDisplayName" class="form-input" />
                            </div>
                            <div class="form-group">
                                <label>Email</label>
                                <input type="email" @bind="EditEmail" class="form-input" />
                            </div>
                            <div class="form-group">
                                <label>Bio</label>
                                <textarea @bind="EditBio" class="form-input form-textarea" rows="4"></textarea>
                            </div>
                            <div class="button-group">
                                <button class="btn btn-primary" @onclick="SaveProfile">Save Changes</button>
                                <button class="btn btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
                            </div>
                        </div>
                    </div>
                }
            </section>
        }
        else if (ActiveSection == "Notifications")
        {
            <section class="settings-section">
                <h2>Notification Preferences</h2>
                @if (NotifPrefs is not null)
                {
                    <div class="toggle-group">
                        <div class="toggle-item">
                            <label class="toggle-label">
                                <span>Email Notifications</span>
                                <label class="switch">
                                    <input type="checkbox" @bind="EditEmailNotifications" />
                                    <span class="slider"></span>
                                </label>
                            </label>
                        </div>
                        <div class="toggle-item">
                            <label class="toggle-label">
                                <span>Push Notifications</span>
                                <label class="switch">
                                    <input type="checkbox" @bind="EditPushNotifications" />
                                    <span class="slider"></span>
                                </label>
                            </label>
                        </div>
                        <div class="toggle-item">
                            <label class="toggle-label">
                                <span>Weekly Digest</span>
                                <label class="switch">
                                    <input type="checkbox" @bind="EditWeeklyDigest" />
                                    <span class="slider"></span>
                                </label>
                            </label>
                        </div>
                    </div>

                    <h3>Muted Channels</h3>
                    <div class="channel-list">
                        @foreach (var channel in EditMutedChannels)
                        {
                            <div class="channel-item">
                                <label>
                                    <input type="checkbox" checked="@channel.Muted"
                                           @onchange="(e) => ToggleChannel(channel.Name, (bool)(e.Value ?? false))" />
                                    <span>#@channel.Name</span>
                                </label>
                            </div>
                        }
                    </div>

                    <div class="button-group">
                        <button class="btn btn-primary" @onclick="SaveNotifications">Save Preferences</button>
                    </div>
                }
            </section>
        }
        else if (ActiveSection == "Security")
        {
            <section class="settings-section">
                <h2>Security Settings</h2>
                @if (Security is not null)
                {
                    <div class="security-panel">
                        <div class="expandable-panel">
                            <button class="panel-header" @onclick="TogglePasswordPanel">
                                <span>Change Password</span>
                                <span class="expand-icon">@(PasswordPanelOpen ? "▼" : "▶")</span>
                            </button>
                            @if (PasswordPanelOpen)
                            {
                                <div class="panel-body">
                                    <div class="form-group">
                                        <label>Current Password</label>
                                        <input type="password" @bind="CurrentPassword" class="form-input" />
                                    </div>
                                    <div class="form-group">
                                        <label>New Password</label>
                                        <input type="password" @bind="NewPassword" class="form-input" />
                                    </div>
                                    <div class="form-group">
                                        <label>Confirm New Password</label>
                                        <input type="password" @bind="ConfirmPassword" class="form-input" />
                                    </div>
                                    @if (!string.IsNullOrEmpty(PasswordError))
                                    {
                                        <p class="error-message">@PasswordError</p>
                                    }
                                    <button class="btn btn-primary" @onclick="UpdatePassword">Update Password</button>
                                </div>
                            }
                        </div>

                        <div class="toggle-item" style="margin-top: 1.5rem;">
                            <label class="toggle-label">
                                <span>
                                    Two-Factor Authentication
                                    <span class="status-indicator @(Security.TwoFactorEnabled ? "status-enabled" : "status-disabled")">
                                        @(Security.TwoFactorEnabled ? "Enabled" : "Disabled")
                                    </span>
                                </span>
                                <label class="switch">
                                    <input type="checkbox" @bind="EditTwoFactor" />
                                    <span class="slider"></span>
                                </label>
                            </label>
                        </div>

                        @if (Security.LastPasswordChange.HasValue)
                        {
                            <p class="info-text">Last password change: @Security.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
                        }

                        <h3>Active Sessions</h3>
                        <div class="sessions-table-wrapper">
                            <table class="sessions-table">
                                <thead>
                                    <tr>
                                        <th>Device</th>
                                        <th>Location</th>
                                        <th>Last Active</th>
                                        <th>Action</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    @foreach (var session in Security.Sessions)
                                    {
                                        <tr>
                                            <td>@session.Device</td>
                                            <td>@session.Location</td>
                                            <td>@FormatLastActive(session.LastActive)</td>
                                            <td>
                                                @if (session.Id != Security.Sessions.FirstOrDefault()?.Id)
                                                {
                                                    <button class="btn btn-danger btn-sm" @onclick="() => ConfirmRevokeSession(session)">
                                                        Revoke
                                                    </button>
                                                }
                                                else
                                                {
                                                    <span class="current-badge">Current</span>
                                                }
                                            </td>
                                        </tr>
                                    }
                                </tbody>
                            </table>
                        </div>
                    </div>

                    @if (ShowRevokeConfirmation)
                    {
                        <div class="modal-overlay" @onclick="CancelRevoke">
                            <div class="modal" @onclick:stopPropagation="true">
                                <h3>Revoke Session</h3>
                                <p>Are you sure you want to revoke the session on <strong>@SessionToRevoke?.Device</strong> from <strong>@SessionToRevoke?.Location</strong>?</p>
                                <div class="button-group">
                                    <button class="btn btn-danger" @onclick="RevokeSession">Revoke</button>
                                    <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                                </div>
                            </div>
                        </div>
                    }
                }
            </section>
        }
        else if (ActiveSection == "Appearance")
        {
            <section class="settings-section">
                <h2>Appearance</h2>
                @if (Appearance is not null)
                {
                    <div class="appearance-options">
                        <div class="form-group">
                            <label><strong>Theme</strong></label>
                            <div class="radio-group">
                                <label class="radio-label">
                                    <input type="radio" name="theme" value="Light" checked="@(EditTheme == "Light")" @onchange='() => EditTheme = "Light"' /> Light
                                </label>
                                <label class="radio-label">
                                    <input type="radio" name="theme" value="Dark" checked="@(EditTheme == "Dark")" @onchange='() => EditTheme = "Dark"' /> Dark
                                </label>
                                <label class="radio-label">
                                    <input type="radio" name="theme" value="System" checked="@(EditTheme == "System")" @onchange='() => EditTheme = "System"' /> System
                                </label>
                            </div>
                        </div>

                        <div class="form-group">
                            <label><strong>Font Size</strong></label>
                            <div class="radio-group">
                                <label class="radio-label">
                                    <input type="radio" name="fontSize" value="Small" checked="@(EditFontSize == "Small")" @onchange='() => EditFontSize = "Small"' /> Small
                                </label>
                                <label class="radio-label">
                                    <input type="radio" name="fontSize" value="Medium" checked="@(EditFontSize == "Medium")" @onchange='() => EditFontSize = "Medium"' /> Medium
                                </label>
                                <label class="radio-label">
                                    <input type="radio" name="fontSize" value="Large" checked="@(EditFontSize == "Large")" @onchange='() => EditFontSize = "Large"' /> Large
                                </label>
                            </div>
                        </div>

                        <div class="form-group">
                            <label><strong>Language</strong></label>
                            <select @bind="EditLanguage" class="form-input form-select">
                                <option value="English">English</option>
                                <option value="Spanish">Spanish</option>
                                <option value="French">French</option>
                                <option value="German">German</option>
                                <option value="Japanese">Japanese</option>
                                <option value="Chinese">Chinese</option>
                            </select>
                        </div>

                        <div class="toggle-item">
                            <label class="toggle-label">
                                <span>Compact Mode</span>
                                <label class="switch">
                                    <input type="checkbox" @bind="EditCompactMode" />
                                    <span class="slider"></span>
                                </label>
                            </label>
                        </div>

                        <h3>Live Preview</h3>
                        <div class="live-preview @GetPreviewClasses()">
                            <div class="preview-header">Settings Dashboard</div>
                            <p class="preview-text">This is how your content will look with the selected appearance settings.</p>
                            <div class="preview-card">
                                <span class="preview-card-title">Sample Card</span>
                                <span class="preview-card-body">Content appears here with your chosen theme and font settings.</span>
                            </div>
                        </div>

                        <div class="button-group">
                            <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>
                        </div>
                    </div>
                }
            </section>
        }
    </main>
</div>

@code {
    private string ActiveSection { get; set; } = "Profile";

    // Toast
    private string? ToastMessage { get; set; }
    private string ToastType { get; set; } = "toast-success";

    // Profile
    private UserProfile? Profile { get; set; }
    private string EditDisplayName { get; set; } = "";
    private string EditEmail { get; set; } = "";
    private string EditBio { get; set; } = "";
    private string EditDisplayAvatarUrl { get; set; } = "";

    // Notifications
    private NotificationPrefs? NotifPrefs { get; set; }
    private bool EditEmailNotifications { get; set; }
    private bool EditPushNotifications { get; set; }
    private bool EditWeeklyDigest { get; set; }
    private List<ChannelState> EditMutedChannels { get; set; } = new();

    // Security
    private SecuritySettings? Security { get; set; }
    private bool PasswordPanelOpen { get; set; }
    private string CurrentPassword { get; set; } = "";
    private string NewPassword { get; set; } = "";
    private string ConfirmPassword { get; set; } = "";
    private string? PasswordError { get; set; }
    private bool EditTwoFactor { get; set; }
    private bool ShowRevokeConfirmation { get; set; }
    private ActiveSession? SessionToRevoke { get; set; }

    // Appearance
    private AppearanceSettings? Appearance { get; set; }
    private string EditTheme { get; set; } = "Light";
    private string EditFontSize { get; set; } = "Medium";
    private string EditLanguage { get; set; } = "English";
    private bool EditCompactMode { get; set; }

    protected override async Task OnInitializedAsync()
    {
        await LoadProfile();
        await LoadNotifications();
        await LoadSecurity();
        await LoadAppearance();
    }

    private void SetSection(string section) => ActiveSection = section;

    // Profile methods
    private async Task LoadProfile()
    {
        Profile = await SettingsService.GetProfileAsync();
        PopulateProfileFields();
    }

    private void PopulateProfileFields()
    {
        if (Profile is null) return;
        EditDisplayName = Profile.DisplayName;
        EditEmail = Profile.Email;
        EditBio = Profile.Bio;
        EditDisplayAvatarUrl = Profile.AvatarUrl;
    }

    private async Task SaveProfile()
    {
        var updated = new UserProfile(EditDisplayName, EditEmail, EditDisplayAvatarUrl, EditBio);
        await SettingsService.SaveProfileAsync(updated);
        Profile = updated;
        ShowToast("Profile saved successfully!", "toast-success");
    }

    private void DiscardProfileChanges()
    {
        PopulateProfileFields();
        ShowToast("Changes discarded.", "toast-info");
    }

    // Notification methods
    private async Task LoadNotifications()
    {
        NotifPrefs = await SettingsService.GetNotificationPrefsAsync();
        EditEmailNotifications = NotifPrefs.EmailNotifications;
        EditPushNotifications = NotifPrefs.PushNotifications;
        EditWeeklyDigest = NotifPrefs.WeeklyDigest;
        EditMutedChannels = NotifPrefs.MutedChannels.Select(c => new ChannelState(c, true)).ToList();
    }

    private void ToggleChannel(string name, bool muted)
    {
        var ch = EditMutedChannels.FirstOrDefault(c => c.Name == name);
        if (ch is not null) ch.Muted = muted;
    }

    private async Task SaveNotifications()
    {
        var mutedChannels = EditMutedChannels.Where(c => c.Muted).Select(c => c.Name).ToList();
        var prefs = new NotificationPrefs(EditEmailNotifications, EditPushNotifications, EditWeeklyDigest, mutedChannels);
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        NotifPrefs = prefs;
        ShowToast("Notification preferences saved!", "toast-success");
    }

    // Security methods
    private async Task LoadSecurity()
    {
        Security = await SettingsService.GetSecuritySettingsAsync();
        EditTwoFactor = Security.TwoFactorEnabled;
    }

    private void TogglePasswordPanel() => PasswordPanelOpen = !PasswordPanelOpen;

    private async Task UpdatePassword()
    {
        PasswordError = null;
        if (string.IsNullOrWhiteSpace(CurrentPassword) || string.IsNullOrWhiteSpace(NewPassword))
        {
            PasswordError = "All fields are required.";
            return;
        }
        if (NewPassword != ConfirmPassword)
        {
            PasswordError = "New passwords do not match.";
            return;
        }
        if (NewPassword.Length < 8)
        {
            PasswordError = "Password must be at least 8 characters.";
            return;
        }
        await SettingsService.ChangePasswordAsync(CurrentPassword, NewPassword);
        CurrentPassword = "";
        NewPassword = "";
        ConfirmPassword = "";
        PasswordPanelOpen = false;
        await LoadSecurity();
        ShowToast("Password updated successfully!", "toast-success");
    }

    private void ConfirmRevokeSession(ActiveSession session)
    {
        SessionToRevoke = session;
        ShowRevokeConfirmation = true;
    }

    private void CancelRevoke()
    {
        ShowRevokeConfirmation = false;
        SessionToRevoke = null;
    }

    private async Task RevokeSession()
    {
        if (SessionToRevoke is not null)
        {
            await SettingsService.RevokeSessionAsync(SessionToRevoke.Id);
            await LoadSecurity();
            ShowToast($"Session on {SessionToRevoke.Device} revoked.", "toast-success");
